// English translations of the legal drafts and the accessibility statement (spec 21). Plain data/templates, no imports:
// legal.mjs passes the helpers it uses for the Hebrew pages, so both languages share structure, contact links and fill-ins.
//   h = { fill, phone, mail, section, toc, draft, updated, a11yCheck }
// These are DRAFT TRANSLATIONS pending legal review; the Hebrew version prevails.

export function termsEn(h) {
  const { fill, phone, mail, section, toc, draft, updated } = h;
  const items = [['t-about', 'Who we are and what we do'], ['t-use', 'Using the site'], ['t-prices', 'Prices, availability and price checks'], ['t-order', 'Offer, booking and payment'], ['t-cancel', 'Cancellations and changes'], ['t-consumer', 'Cancelling a transaction under the Consumer Protection Law'], ['t-docs', 'Passports, visas and health'], ['t-airline', 'Responsibility of airlines and suppliers'], ['t-liability', 'Limitation of liability'], ['t-content', 'Content, inspiration and the service bot'], ['t-account', 'Customer account'], ['t-privacy', 'Privacy'], ['t-ip', 'Intellectual property'], ['t-law', 'Governing law and jurisdiction'], ['t-contact', 'Contact us']];
  return `${draft}<p class="micro-copy">Last updated: ${updated}. These terms apply equally to all genders.</p>${toc(items)}<div class="article-body legal-body">
  ${section('t-about', '1. Who we are and what we do', `<p>This site is operated by Gerbi Tours (${fill('legal entity name')}, company/business no. ${fill('number')}, address: ${fill('registered address')}) — “the Agency”, “we”, “us”.</p>
   <p>Gerbi Tours is a travel agency. We search for flights and travel services for you through suppliers (booking systems and wholesalers) and with the airlines, and we provide the service ourselves: answering your questions, checking prices, preparing an offer, booking and support. <strong>We are not the airline and do not operate the flight</strong>; the carriage itself is provided by the airline under its own conditions of carriage.</p>`)}
  ${section('t-use', '2. Using the site', `<p>Use of the site is subject to these terms. If you do not agree to them, please do not use the site. You may not perform automated actions on the site (scraping, flooding it with requests), impersonate another person or submit false information. We may block any use that harms the site, our suppliers or other customers.</p>`)}
  ${section('t-prices', '3. Prices, availability and price checks', `<ul><li>Flight prices are received from suppliers in real time and change constantly. <strong>A price shown on the site is not a binding offer and does not hold a seat</strong>; it becomes final only when the ticket is issued.</li>
   <li>A “price check” confirms the price and availability with the supplier at the moment of the check only. Even a checked price may change until booking and ticketing.</li>
   <li>Prices in shekels are calculated at the transfers and cheques selling rate, and may therefore change with the exchange rate. The amount to be charged will be set out in the offer you receive.</li>
   <li>The price includes the taxes and charges reported by the supplier. ${fill('whether the price includes an agency service fee, and how much')}. Baggage, seat selection and additional services are as stated in the flight details and fare rules.</li>
   <li>“Holiday ideas”, hotels and packages shown for inspiration are illustrative estimates only and are not an offer.</li>
   <li>A clerical or obvious pricing error does not bind the Agency; in such a case we will contact you before any charge.</li></ul>`)}
  ${section('t-order', '4. Offer, booking and payment', `<ul><li>At this stage the site does not offer online booking or payment. After you contact us or run a price check, a Gerbi Tours agent will get back to you with a written offer that includes the final price, flight details, fare rules (baggage, changes and cancellations) and service fees.</li>
   <li>A booking is made only after you expressly approve the offer and pay by ${fill('payment method and payment processor')}. The transaction is concluded when we confirm the booking in writing.</li>
   <li>You are responsible for providing passenger names exactly as they appear in the passport (in Latin letters), dates of birth and correct contact details. Correcting a name after ticketing may be prohibited or involve a fee under the airline’s rules.</li>
   <li>After ticketing, you will receive the ticket/booking confirmation and a receipt or invoice.</li></ul>`)}
  ${section('t-cancel', '5. Cancellations and changes', `<ul><li>Cancelling or changing a ticket is subject to the <strong>airline’s fare rules</strong>, which will be detailed in the offer. Many tickets are non-refundable or non-changeable, or a change involves change fees and fare differences.</li>
   <li>For a cancellation or change we handle on your behalf, the Agency will charge a service fee of ${fill('cancellation/change service fee')}, subject to the law, including the caps set by the Consumer Protection Law.</li>
   <li>Cancellation and change requests must be sent in writing (email, WhatsApp or the contact form). Requests are handled on business days ${fill('business days and hours')}.</li>
   <li>Cancellation or change of a flight by the airline: rights to compensation, refunds and assistance are granted under the applicable law, including the Aviation Services Law (Compensation and Assistance for Flight Cancellation or Change of Conditions), 5772–2012, and, for flights from Europe, Regulation (EC) 261/2004. We will assist you with the airline; the obligation to compensate lies with the airline.</li></ul>`)}
  ${section('t-consumer', '6. Cancelling a transaction under the Consumer Protection Law', `<p>If your booking was made as a distance transaction (by phone, email, WhatsApp or online), you have a right of cancellation under Section 14C of the Consumer Protection Law, 5741–1981, and the Consumer Protection Regulations (Cancellation of Transaction), 5771–2010, subject to their conditions and exceptions — in particular for travel, accommodation and holiday services where the service date is close to the cancellation date.</p>
   <p>Upon a lawful cancellation, a cancellation fee will be charged that does not exceed the amount set by law, plus — to the extent the law permits — amounts paid or payable to a supplier or airline that are non-refundable. ${fill('final wording of the cancellation fee mechanism — after legal review')}.</p>
   <p>To give notice of cancellation: email ${mail()}, phone ${phone()} or the <a href="#/contact">contact form</a>. Please include your name, booking number and contact details.</p>`)}
  ${section('t-docs', '7. Passports, visas and health', `<p>Travelers are responsible for holding a valid passport (for most countries — at least 6 months beyond the return date), entry and transit visas (including ESTA/ETA and similar), health and vaccination requirements, and travel insurance. Any information we provide on these matters is general and does not replace checking with the relevant country’s mission or the Ministry of Foreign Affairs. We strongly recommend buying travel insurance, including cancellation cover.</p>`)}
  ${section('t-airline', '8. Responsibility of airlines and suppliers', `<p>Carriage, schedules, baggage, check-in, boarding and ground services are provided by the airlines and suppliers and are their responsibility, under their own terms. Delays, cancellations, rerouting, lost baggage or damage in flight are the airline’s responsibility, subject to international conventions and the law. Gerbi Tours is responsible for the service it provides itself: accurately passing on the information it received, making the booking as you approved it, and reasonably handling your requests.</p>`)}
  ${section('t-liability', '9. Limitation of liability', `<p>To the extent permitted by law, our liability for any damage related to a booking is limited to the amount actually paid to us for that booking, and we are not liable for indirect or consequential damage. Nothing in this section limits rights that cannot be waived under the Consumer Protection Law or any other law, or liability for damage caused by negligence or wilful misconduct.</p>`)}
  ${section('t-content', '10. Content, inspiration and the service bot', `<p>Guides, recommendations, estimates and answers from Gerbi and the service bot are provided for your convenience and may contain inaccuracies. Automated answers are not binding; the binding terms are those in the offer and the booking confirmation. You can ask for a human agent at any time.</p>`)}
  ${section('t-account', '11. Customer account', `<p>Opening an account is optional. Keep your password safe and let us know if you believe your account has been used without authorization. You can delete your account at any time from your personal area.</p>`)}
  ${section('t-privacy', '12. Privacy', `<p>The use of personal information is described in the <a href="#/privacy">privacy policy</a>, which forms part of these terms.</p>`)}
  ${section('t-ip', '13. Intellectual property', `<p>The content, design, marks, the “Gerbi” character and the code on the site belong to Gerbi Tours or to their respective rights holders. You may not copy them or use them commercially without written permission.</p>`)}
  ${section('t-law', '14. Governing law and jurisdiction', `<p>These terms and any transaction on the site are governed exclusively by Israeli law. Exclusive jurisdiction lies with the competent courts in ${fill('district/city')}, without derogating from a consumer’s right to apply to the competent court according to their place of residence, as provided by law.</p>`)}
  ${section('t-contact', '15. Contact us', `<p>Gerbi Tours · phone ${phone()} · email ${mail()} · <a href="#/contact">contact form</a> · address: ${fill('postal address')}.</p>`)}
  </div>`;
}

export function privacyEn(h) {
  const { fill, phone, mail, section, toc, draft, updated } = h;
  const items = [['p-who', 'Who is responsible for your data'], ['p-what', 'What information we collect'], ['p-why', 'How we use the information'], ['p-legal', 'Do you have to provide information'], ['p-share', 'Who receives the information'], ['p-abroad', 'Transfers abroad'], ['p-keep', 'How long we keep it'], ['p-device', 'Cookies and on-device storage'], ['p-rights', 'Your rights'], ['p-security', 'Information security'], ['p-marketing', 'Marketing messages'], ['p-kids', 'Minors'], ['p-changes', 'Changes and contact']];
  const row = (cat, examples, purpose, keep) => `<tr><th scope="row">${cat}</th><td>${examples}</td><td>${purpose}</td><td>${keep}</td></tr>`;
  return `${draft}<p class="micro-copy">Last updated: ${updated}. This policy was written under the Israeli Privacy Protection Law, 5741–1981, as amended by Amendment 13 (in force since August 2025).</p>${toc(items)}<div class="article-body legal-body">
  ${section('p-who', '1. Who is responsible for your data', `<p>Database controller: Gerbi Tours (${fill('legal entity name and company no.')}). For privacy enquiries: ${mail()} · ${phone()}. ${fill('name of the privacy protection officer, if appointed')}.</p>`)}
  ${section('p-what', '2. What information we collect, why and for how long', `<div class="table-scroll" tabindex="0" role="region" aria-label="Table of information types"><table class="legal-table"><caption class="sr-only">Types of information, their purpose and retention period</caption><thead><tr><th scope="col">Type of information</th><th scope="col">Examples</th><th scope="col">Purpose</th><th scope="col">Retention</th></tr></thead><tbody>
   ${row('Customer account (optional)', 'Name, email, phone, password (stored only as a one-way hash), marketing consent and its date, saved trips and flights, favorites, up to 20 recent searches (without prices), a summary of your enquiries', 'Providing the account service and continuing from any device', 'Until the account is deleted; sign-in — up to 30 days')}
   ${row('Enquiries (leads)', 'Name, phone, email, preferred channel, trip and request details, consent and its wording', 'Getting back to you, preparing an offer and providing service', fill('retention period for enquiries'))}
   ${row('Conversations with the service bot', 'The content of messages in the conversation, a conversation ID and, on WhatsApp, your phone number', 'Answering, handing over to an agent and improving answers', 'Up to 90 days')}
   ${row('Flight searches and price checks', 'Route, dates, passenger mix', 'Showing flights and prices', 'In a temporary cache (minutes); not stored with your name unless you are signed in')}
   ${row('Requests to Gerbi (planner)', 'The request text; with consent to learning — keywords and tags with a hashed identifier', 'Understanding the request and improving recommendations', 'Up to 30 days in cache; aggregate learning data without identity')}
   ${row('Usage and security data', 'IP address, browser type, request times, error logs', 'Security, abuse prevention, rate limiting', fill('log retention period'))}
   </tbody></table></div>
   <p>We do not collect credit card details or passport numbers on the site. Please do not send them through the bot or the forms; passenger and payment details are given to an agent only at the booking stage and through ${fill('secure channel for passenger and payment details')}.</p>`)}
  ${section('p-why', '3. How we use the information', `<ul><li>Providing the service: search, price checks, preparing offers, booking and customer service.</li><li>Managing your account and saved items.</li><li>Answering on the bot and WhatsApp and handing over to an agent.</li><li>Improving recommendations and ranking — in aggregate wherever possible.</li><li>Securing the site and preventing fraud and abuse.</li><li>Complying with legal obligations (accounting, tax, consumer law).</li><li>Marketing messages — only if you have expressly consented.</li></ul>`)}
  ${section('p-legal', '4. Do you have to provide information', `<p>You are under no legal obligation to provide us with information. Without contact details we cannot get back to you, and without passenger details we cannot book for you. You can browse, search and save on your device without providing any details.</p>`)}
  ${section('p-share', '5. Who receives the information (processors and other parties)', `<p>We do not sell personal information. Information is shared only with parties needed to provide the service, and only to the extent necessary:</p>
   <ul><li><strong>Hosting and infrastructure:</strong> Vercel (site and server hosting), Upstash (cloud database for accounts, enquiries and conversations).</li>
   <li><strong>Flight suppliers and airlines:</strong> search details; and at the booking stage — the passenger details required for ticketing.</li>
   <li><strong>Email:</strong> Resend — for sending verification codes, password resets and service messages.</li>
   <li><strong>WhatsApp:</strong> Meta (WhatsApp Business Cloud API) — when you contact us on WhatsApp.</li>
   <li><strong>AI providers:</strong> Anthropic${fill('additional AI providers, if added')} — only the text of the request or message, after phone numbers and emails are removed, to understand the request and draft a reply. No name or identifier is sent. Under the providers’ terms, the information is not used to train their models (${fill('verify against the provider contracts')}).</li>
   <li><strong>Fonts:</strong> Google Fonts — your browser loads the font from it, so your IP address is exposed to it.</li>
   <li><strong>Authorities:</strong> where required by law, or to protect our rights.</li></ul>`)}
  ${section('p-abroad', '6. Transferring information outside Israel', `<p>Some of the providers above store or process information outside Israel (for example in the European Union and the USA), subject to the Privacy Protection Regulations (Transfer of Information to Databases Abroad) and the providers’ contractual commitments. ${fill('actual storage regions: Vercel / Upstash')}.</p>`)}
  ${section('p-keep', '7. How long we keep it', `<p>The retention period for each type of information is listed in the table above. At the end of the period the information is deleted or anonymized, unless the law requires us to keep it longer (for example, accounting records).</p>`)}
  ${section('p-device', '8. Cookies and on-device storage', `<p>The site uses a single cookie, <span dir="ltr">gerbi_sid</span>, which is required to sign in to your account (secure, for 30 days). We do not use advertising cookies or third-party tracking. In addition, the site stores on your device (localStorage / sessionStorage) your favorites, saved trips and flights, comparisons, style preferences, display settings and the current bot conversation. Clearing the site’s data in your browser deletes them.</p>`)}
  ${section('p-rights', '9. Your rights', `<ul><li><strong>Access</strong> to the information held about you (Section 13 of the Law). In your account you can download a full copy at any time.</li><li><strong>Correction</strong> of information that is wrong, incomplete or out of date (Section 14).</li><li><strong>Deletion</strong> — deleting your account from your personal area, or asking us to delete enquiries and conversations.</li><li><strong>Unsubscribing</strong> from marketing at any time (Section 17F of the Law and Section 30A of the Communications Law).</li><li><strong>Withdrawing consent</strong> to learning and marketing — in your account settings or by contacting us.</li></ul>
   <p>For requests: ${mail()}. We will reply within ${fill('number of days')} and no later than the time limits set by law. If we have not answered, you may contact the Privacy Protection Authority.</p>`)}
  ${section('p-security', '10. Information security', `<p>We take reasonable measures under the Privacy Protection Regulations (Data Security), 5777–2017: encryption in transit (HTTPS), one-way hashed passwords, limits on sign-in attempts, access restricted to authorized staff, and access logs. No system is completely immune; if a serious security incident occurs, we will act as required by law.</p>`)}
  ${section('p-marketing', '11. Marketing messages', `<p>We send marketing messages only if you have ticked an explicit consent box. Every message includes a way to unsubscribe, and you can also opt out in your account.</p>`)}
  ${section('p-kids', '12. Minors', `<p>The service is intended for people aged 18 and over. Children’s details are provided to us only by a parent or guardian and only for the purpose of the booking.</p>`)}
  ${section('p-changes', '13. Changes and contact', `<p>We will update this policy from time to time; the date of the last update appears at the top of the page, and we will also announce material changes on the site. Questions: ${mail()} · ${phone()} · <a href="#/contact">contact us</a>. See also the <a href="#/terms">terms of use</a>.</p>`)}
  </div>`;
}

export function accessibilityEn(h) {
  const { fill, phone, mail, section, draft, a11yCheck } = h;
  const done = ['A “Skip to content” link at the top of every page, and a single main heading per screen that receives focus when you move between pages.', 'Full keyboard navigation: Tab and Shift+Tab, Enter and Space to activate, Escape to close dialogs; a clear focus outline on every component.', 'An accessible date picker: arrow keys move between days, Page Up/Down between months, and date fields accept direct typing.', 'Dialogs (dates, travelers, price check, service chat) are announced as dialogs, return focus to the button that opened them and fill the whole screen on phones.', 'Every form field has a label; error messages are linked to their field and announced, and focus moves to the first invalid field.', 'Status messages (search results, saving, bot replies) are announced to screen readers (aria-live).', 'Page regions (header, navigation, main content, footer) are marked up, and the page language and direction are declared (English, left to right; on the Hebrew site, Hebrew, right to left).', 'Color contrast at level AA, text that can be enlarged to 200% without loss of content, and a layout that adapts down to a width of 320 pixels.', 'Buttons and touch targets of at least 44×44 pixels on phones, and input fields sized so they do not trigger automatic zoom.', 'The device’s “reduce motion” setting is respected, and animations can be stopped in the display settings.', 'Content images have alternative text; decorative icons are hidden from screen readers.'];
  const limits = ['Flight details (airline codes, times and airport names) come from suppliers and are shown as received; Latin abbreviations may appear.', 'Images in blog posts uploaded by the site team may lack a full text alternative — we are working to complete them.', 'Answers from the service bot are generated automatically; you can ask for a human agent at any point.', 'External services (WhatsApp, airline websites) are not under our control, and their accessibility is the responsibility of their operators.', `The site has not yet been reviewed by a certified service accessibility auditor or tested with screen reader users. ${fill('date of the certified accessibility audit, if performed')}`];
  return `${draft}<div class="article-body legal-body">
  ${section('a-commit', 'Our commitment', `<p>Gerbi Tours is committed to providing equal service to all customers, including people with disabilities. We have invested in making the site accessible, so it is comfortable to use with a keyboard, a screen reader, zoomed-in display and mobile devices.</p>`)}
  ${section('a-level', 'Accessibility level', `<p>The site has been adapted to the requirements of the Equal Rights for Persons with Disabilities (Service Accessibility Adjustments) Regulations, 5773–2013, and Israeli Standard SI 5568 at level AA, which is based on the WCAG 2.0 guidelines (we also checked against WCAG 2.1 level AA). Testing was carried out in Chrome and Safari on desktop and on phones (iOS and Android), with the keyboard only and with automated testing tools (axe-core).</p>`)}
  ${section('a-done', 'What we have made accessible', `<ul>${done.map(t => `<li>${t}</li>`).join('')}</ul>`)}
  ${section('a-limits', 'Known limitations', `<p>Despite our efforts, some parts of the site may not yet be fully accessible:</p><ul>${limits.map(t => `<li>${t}</li>`).join('')}</ul><p>If you run into any difficulty, please let us know — we will fix it and, in the meantime, serve you another way (phone, email or WhatsApp).</p>`)}
  ${section('a-physical', 'Accessibility arrangements for our service', `<p>${fill('whether there is an office open to the public. If so — address, accessible parking, accessible entrance, accessible restrooms and hours; if not — “Service is provided by phone, email, WhatsApp and the website only”')}.</p><p>Accessibility requests for the holiday itself (a wheelchair at the airport, an accessible room, assistance) can be noted in the contact form or in your trip plan, and we will check them with the suppliers.</p>`)}
  ${section('a-contact', 'Accessibility coordinator and enquiries', `<dl class="legal-dl"><dt>Name</dt><dd>${fill('accessibility coordinator name')}</dd><dt>Phone</dt><dd>${fill('direct phone')}</dd><dt>Email</dt><dd>${fill('email for accessibility enquiries')}</dd><dt>Postal address</dt><dd>${fill('address')}</dd></dl><p>You can also contact us by phone ${phone()}, by email ${mail()} or through the <a href="#/contact">contact form</a>. We will reply within ${fill('number of business days')}.</p>`)}
  ${section('a-date', 'Statement updates', `<p>Last accessibility review: <time datetime="2026-11-15">${a11yCheck}</time>. This statement was updated on <time datetime="2026-11-15">${a11yCheck}</time>.</p>`)}
  </div>`;
}
